#include <bits/stdc++.h>
using namespace std;

bool checkk(string a, string b, int n) {
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    bool allLess = true;
    bool allGreater = true;

    for (int i = 0; i < n; ++i) {
        if (a[i] >= b[i]) allLess = false;
        if (a[i] <= b[i]) allGreater = false;
    }

    return allLess || allGreater;
}

int main() {
    int n;
    cin >> n;

    string s;
    cin >> s;

    string first = s.substr(0, n);
    string second = s.substr(n, n);

    cout << (checkk(first, second, n) ? "YES" : "NO") << '\n';
    return 0;
}

